SELECT b.brand, b.shift, b.total_net_loss, b.total_return_qty, b.brand_shift_rank, b.cumulative_net_loss_shift FROM ( SELECT i.i_brand AS brand, td.t_shift AS shift, SUM(sr.sr_net_loss) AS total_net_loss, SUM(sr.sr_return_quantity) AS total_return_qty, RANK() OVER (PARTITION BY td.t_shift ORDER BY SUM(sr.sr_net_loss) DESC) AS brand_shift_rank, SUM(SUM(sr.sr_net_loss)) OVER (PARTITION BY td.t_shift ORDER BY SUM(sr.sr_net_loss) DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_loss_shift FROM store_returns sr JOIN item i ON sr.sr_item_sk = i.i_item_sk JOIN time_dim td ON sr.sr_return_time_sk = td.t_time_sk GROUP BY i.i_brand, td.t_shift ) b WHERE b.brand_shift_rank <= 3 ORDER BY b.shift, b.brand_shift_rank
